out={'files':[],'skipped':[],'diffs':[],'diagnostics':[],'history_commands':[],'calibration_files':[],'processes':[]}
for req in REQUESTS:
 p=Path(req['path'])
 try:
  if not p.is_file() or p.stat().st_size>2*1024*1024:raise ValueError('not small regular file')
  if any(x in p.parts for x in ['.ssh','.aws','.env','credentials']):raise ValueError('denied path')
  data=p.read_bytes()
  if p.suffix not in ['.jpg','.npy','.npz'] and sensitive.search(data):out['skipped'].append({'path':str(p),'reason':'sensitive pattern detected, content not transferred'});continue
  if hashlib.sha256(data).hexdigest()!=req['sha256']:raise ValueError('changed after discovery')
  out['files'].append(dict(req,data=base64.b64encode(data).decode('ascii')))
 except Exception as e:out['skipped'].append({'path':str(p),'reason':str(e)})
def command(label,args):
 r=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=dict(os.environ,GIT_OPTIONAL_LOCKS='0',PYTHONDONTWRITEBYTECODE='1'))
 data=r.stdout+r.stderr
 if sensitive.search(data):out['diagnostics'].append({'label':label,'exit':r.returncode,'redacted':True});return
 out['diagnostics'].append({'label':label,'argv':args,'exit':r.returncode,'output':data.decode('utf8','replace')})
home=Path.home()
for name in ['llama.cpp','llama5050gpu.cpp','llama-qwen3-gpu']:
 repo=home/'robi-llm'/name
 r=subprocess.run(['git','-C',str(repo),'diff','--binary','HEAD'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=dict(os.environ,GIT_OPTIONAL_LOCKS='0'))
 if not sensitive.search(r.stdout):out['diffs'].append({'repo':str(repo),'exit':r.returncode,'sha256':hashlib.sha256(r.stdout).hexdigest(),'data':base64.b64encode(r.stdout).decode('ascii')})
for label,args in [('gcc8',['/usr/bin/gcc-8','--version']),('g++8',['/usr/bin/g++-8','--version']),('custom-cmake',[str(home/'robi-llm/cmake-3.28.6-linux-aarch64/bin/cmake'),'--version']),('usb-tree',['lsusb','-t']),('kernel-config',['zcat','/proc/config.gz'])]:
 try:command(label,args)
 except OSError as e:out['diagnostics'].append({'label':label,'error':type(e).__name__})
# Query-only source/metadata searches; do not call V4L2 or application binaries.
for base in [home/'ps4_calib',home/'robi-llm']:
 if not base.exists():continue
 for p in base.iterdir():
  if p.is_file():out['calibration_files'].append({'path':str(p),'bytes':p.stat().st_size})
# History is parsed on Nano, only narrowly relevant commands leave it; omit complete history.
for name in ['.bash_history','.zsh_history']:
 p=home/name
 if not p.is_file():continue
 for l in p.read_bytes().splitlines():
  if len(l)>1500 or sensitive.search(l):continue
  if re.search(rb'(^|[;&| ]|:[0-9 ]*;)(cmake|\./[^ ]*llama-(cli|server|bench)|python3? +[^ ;]*ps4[^ ;]*\.py|sudo +python3? +ps4eye_init\.py|v4l2-ctl)( |$)',l):
   # Do not export shell auth/env settings even if attached to otherwise relevant command.
   if re.search(rb'(?i)(password|passwd|token|secret|api[_-]?key|\.ssh|\.env|sshpass|curl|wget|export )',l):continue
   out['history_commands'].append({'source':str(p),'command':l.decode('utf8','replace')})
# Process arguments: only application processes and omit any credential-bearing command entirely.
for proc in Path('/proc').glob('[0-9]*'):
 try:
  argv=(proc/'cmdline').read_bytes().split(b'\0');argv=[x for x in argv if x]
  if not argv:continue
  exe=os.path.basename(argv[0].decode('utf8','replace'))
  if not (exe.startswith('llama-') or (exe.startswith('python') and any(b'ps4' in x and x.endswith(b'.py') for x in argv[1:3]))):continue
  if re.search(rb'(?i)(password|passwd|token|secret|api[_-]?key|Authorization)',b' '.join(argv)):continue
  out['processes'].append({'pid':proc.name,'argv':[x.decode('utf8','replace') for x in argv]})
 except OSError:pass
# Include dependency provenance from existing dependency files, not a new preprocessor run.
out['include_dependencies']=[]
for name in ['llama.cpp','llama5050gpu.cpp','llama-qwen3-gpu']:
 repo=home/'robi-llm'/name
 for root,dirs,files in os.walk(str(repo)):
  dirs[:]=[x for x in dirs if x!='.git']
  for filename in files:
   if filename.endswith(('.o.d','.d')) or filename in ['compiler_depend.make','compiler_depend.internal']:
    q=Path(root)/filename
    try:
     if q.stat().st_size>16*1024*1024:continue
     data=q.read_text(errors='replace')
     paths=sorted(set(re.findall(r'[^\s\\]*cuda_bf16\.(?:h|hpp)',data)))
     if paths:out['include_dependencies'].append({'path':str(q),'bf16_paths':paths})
    except OSError:pass
json.dump(out,sys.stdout,ensure_ascii=False)
